.ds-button { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; border: 1px solid transparent; border-radius: 0; background: transparent; color: var(--foreground, #171714); font: 500 14px/20px var(--pi-font-sans, InterVariable, Inter, ui-sans-serif, system-ui, sans-serif); padding: 0; cursor: pointer; white-space: nowrap; transition: background-color 120ms ease-out; }
.ds-button svg { width: 20px; height: 20px; pointer-events: none; }
.ds-button:hover, .ds-button[aria-expanded="true"] { background: var(--muted, #ecece6); color: var(--foreground, #171714); }
:host-context(.dark) .ds-ghost:hover { background: color-mix(in oklab, var(--muted, #292925) 50%, transparent); }
.ds-button:focus-visible { border-color: var(--ring, #a9a9a0); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #a9a9a0) 50%, transparent); outline: 2px solid var(--foreground, #171714); outline-offset: 2px; }
.ds-button:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button:disabled { pointer-events: none; opacity: .5; cursor: default; }
@media (prefers-reduced-motion: reduce) { .ds-button { transition: none; } }
.ds-ghost { width: 32px; height: 40px; } @media (max-width: 760px) { .ds-ghost { width: 44px; height: 44px; } }

