.ds-tracks { list-style: none; padding: 0; margin: 0; background: var(--card, #fffffc); color: var(--card-foreground, #171714); }
.ds-row { box-sizing: border-box; height: 68px; border-bottom: 1px solid var(--border, #d6d6ce); position: relative; }
.ds-row[data-selected="true"] { background: var(--secondary, #ecece6); }
.ds-row[data-selected="true"]::after { content: ""; position: absolute; inset: 3px; border: 1px solid var(--border, #d6d6ce); pointer-events: none; }
.ds-select { display: flex; align-items: center; text-align: left; width: 100%; height: 100%; gap: 10px; background: transparent; border: 0; border-radius: 0; color: inherit; padding: 8px 12px 8px 52px; cursor: pointer; }
.ds-select:focus-visible { outline: 2px solid var(--foreground, #171714); outline-offset: -3px; }
.ds-copy { display: flex; flex-direction: column; flex: 1; min-width: 0; gap: 4px; }
.ds-filename { font: 12px/18px "TX-02", monospace; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-meta { font: 11px/16px "TX-02", monospace; color: var(--muted-foreground, #6a6a64); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-duration { width: 40px; flex: none; text-align: right; font: 11px "TX-02", monospace; font-variant-numeric: tabular-nums; }
.ds-row-play { position: absolute; left: 4px; top: 11px; width: 44px; height: 44px; }
.ds-row-play svg { width: 18px; height: 18px; }
@media (hover: hover) and (pointer: fine) and (min-width: 761px) { .ds-row-play { opacity: 0; pointer-events: none; } .ds-row:hover .ds-row-play, .ds-row:focus-within .ds-row-play { opacity: 1; pointer-events: auto; } }

.ds-seek { appearance: none; display: block; width: 100%; height: 40px; padding: 0; border: 0; border-radius: 0; background: transparent; box-shadow: none; cursor: pointer; touch-action: none; }
.ds-seek:disabled { cursor: default; opacity: .4; background: transparent; }
.ds-seek:focus-visible { outline: 2px solid var(--foreground, #171714); outline-offset: 2px; }
.ds-seek::-webkit-slider-runnable-track { height: 2px; background: var(--muted-foreground, #6a6a64); }
.ds-seek::-moz-range-track { height: 2px; background: var(--muted-foreground, #6a6a64); }
.ds-seek::-webkit-slider-thumb { appearance: none; width: 3px; height: 32px; margin-top: -15px; border: 0; border-radius: 0; background: var(--foreground, #171714); }
.ds-seek::-moz-range-thumb { width: 3px; height: 32px; border: 0; border-radius: 0; background: var(--foreground, #171714); }

